def tr(key: str, lang: str = "kk") -> str:
    return TRANSLATIONS.get(lang, TRANSLATIONS["kk"]).get(key, key)

_SCENE_KEYS = ['Иллюстрация этапов обработки. Движение фигур не показывает оставшееся время.', 'Quality Analyst завершил проверку. Consistency Analyst работает.', 'Consistency Analyst завершил проверку. Quality Analyst работает.', 'Результат восстановлен из кэша — без новых запросов', 'Анализ завершён. PDF недоступен, JSON сохранён.', 'Параллельная проверка · Quality + Consistency', 'Предварительная проверка одним агентом', 'Восстановление сохранённого состояния', 'Анализ завершён. Формирование отчёта', 'Формирование предварительного отчёта', 'Документ передан двум аналитикам', 'Оба анализа переданы аудитору', 'Предварительная проверка', 'Извлечение требований', 'Подготовка документа', 'Проверка остановлена', 'Поиск противоречий', 'Проверка качества', 'Quick · 1 агент', 'Deep · 4 агента', 'PDF недоступен', 'Итоговый аудит', 'Восстановление', 'Отчёт готов', 'Остановлен', 'В работе', 'Завершил', 'Ожидает', 'Из кэша']
_SCENE_PATTERN = re.compile("|".join(map(re.escape, _SCENE_KEYS)))

def localize_scene(html: str, lang: str) -> str:
    """Translate static labels in the existing v0.8.3 scene without modifying its states."""
    return _SCENE_PATTERN.sub(lambda m: tr(m.group(), lang), html).replace('html lang="ru"', f'html lang="{lang}"')

