def localize_graph(graph, lang):
    """Presentation copy; never translate original evidence or exported graph."""
    view = graph.copy()
    severity = {'critical':'Критический','high':'Высокий','medium':'Средний','low':'Низкий'}
    for _, data in view.nodes(data=True):
        if 'type' in data:
            data['type'] = tr(data['type'], lang)
        if data.get('kind') == 'finding' and 'label' in data:
            data['label'] = tr(data['label'], lang)
        if data.get('severity') in severity:
            data['severity'] = tr(severity[data['severity']], lang)
    for _, _, data in view.edges(data=True):
        data['label'] = tr(data['label'], lang)
        if data.get('severity') in severity:
            data['severity'] = tr(severity[data['severity']], lang)
    return view
